interface InitiatorSeed {
  id: string;
  name: string;
  category: InitiatingEventCategory;
  subcategory: string;
  states: string[];
  method: string;
  trip: string;
  safety: string[];
  barrier: BarrierImpactState;
  screening: ScreeningStatus;
  importance: ImportanceLevel;
  basis: string;
}

function buildInitiator(x: InitiatorSeed): InitiatorDefinition {
  return {
    uuid: x.id,
    name: x.name,
    eventType: "INITIATING",
    frequency: 0,
    category: x.category,
    subcategory: x.subcategory,
    applicableStates: x.states,
    identificationMethodIds: [x.method],
    identificationBasis: [x.basis],
    tripParameters: x.trip.length > 0 ? [{ parameter: x.trip, setpoint: 0, uncertainty: 0, basis: x.method }] : [],
    mitigatingSystems: [],
    barrierImpacts: [{ barrierId: "PSB", state: x.barrier, timing: "At initiation", mechanism: x.subcategory }],
    challengedSafetyFunctions: x.safety,
    screeningStatus: x.screening,
    importanceLevel: x.importance,
    implementsSrs: [sr("IE-A5", "A")],
  };
}

const INITIATOR_SEEDS: InitiatorSeed[] = [
  { id: "IE-01", name: "Single primary-pump loss of flow (coastdown)", category: C.TRANSIENT, subcategory: "Loss of forced primary flow", states: ["POS-01", "POS-02"], method: "HBFT", trip: "Subassembly-outlet-temperature / primary underflow", safety: ["Remove core heat", "Control reactivity"], barrier: BarrierImpactState.INTACT, screening: ScreeningStatus.RETAINED, importance: ImportanceLevel.HIGH, basis: "EBR-II Level 1 PRA (ANL-NSE-2, Sec. 5.2.1, Tables 5.5/5.6/5.10) quantifies single primary-pump loss-of-flow from pump binding and motor-generator (M-G) set faults as slow (LF1A), clutch (LF1B) and fast (LF1C) coastdowns, with a data-based frequency of order 5E-1/yr. The protected event is terminated by scram on subassembly-outlet temperature and underflow trips followed by natural-circulation decay-heat removal. Found by the heat-balance fault tree on the forced-flow path." },
  { id: "IE-02", name: "Single primary-pump seizure / immediate flow loss (LF1D)", category: C.TRANSIENT, subcategory: "Loss of forced primary flow", states: ["POS-01", "POS-02"], method: "FMEA", trip: "Primary underflow / subassembly-outlet temperature", safety: ["Remove core heat", "Control reactivity"], barrier: BarrierImpactState.INTACT, screening: ScreeningStatus.RETAINED, importance: ImportanceLevel.MEDIUM, basis: "ANL-NSE-2 Sec. 5.2.1 (Tables 5.6/5.7/5.10) treats an instantaneous one-loop flow loss from primary-pump shaft seizure or an M-G output-breaker trip (LF1D) as a distinct, faster-coastdown initiator within the single-pump loss-of-flow family. Identified by FMEA of the primary-pump and M-G train." },
  { id: "IE-03", name: "Double-pump (both-loop) loss of flow / ULOF precursor (LF2)", category: C.TRANSIENT, subcategory: "Loss of forced primary flow", states: ["POS-01", "POS-02"], method: "MLD", trip: "Primary underflow (both loops) / subassembly-outlet temperature", safety: ["Remove core heat", "Control reactivity"], barrier: BarrierImpactState.INTACT, screening: ScreeningStatus.RETAINED, importance: ImportanceLevel.HIGH, basis: "ANL-NSE-2 Sec. 5.2.2 (Tables 5.7/5.8/5.10) models loss of flow in both primary loops (LF2A-LF2F), dominated by hypothesized common-cause failure of the two M-G sets. This is the protected loss-of-flow design-basis line and the precursor to the unprotected loss of flow (ULOF) demonstrated full-power without scram in the April 1986 SHRT-45R test, where inherent metallic-fuel and structural feedbacks shut the reactor down. EBR-II eliminated one real double-pump LOF caused by a clutch dependency by removing the dependency. Captured top-down by the master logic diagram heat-removal branch." },
  { id: "IE-04", name: "Loss of normal (off-site) power (LONP)", category: C.TRANSIENT, subcategory: "Loss of off-site power", states: ["POS-01", "POS-02", "POS-03", "POS-04"], method: "OEREV", trip: "Loss of bus voltage / primary underflow", safety: ["Remove core heat"], barrier: BarrierImpactState.INTACT, screening: ScreeningStatus.RETAINED, importance: ImportanceLevel.HIGH, basis: "ANL-NSE-2 Sec. 5.2.3.1 (Table 5.10) gives Loss of Normal Power at 1E-1/yr from EBR-II operating data. Plain loss of off-site power occurs about once per year but does not itself trip the plant because EBR-II carries its own hotel load; LONP is the residual where the transfer fails and the primary pumps coast down. The 1991 lessons-learned synthesis identifies unprotected loss of normal power as the most important internal initiator. The auxiliary EM pump on its battery/diesel chain makes the coastdown benign." },
  { id: "IE-05", name: "Loss of secondary (intermediate) sodium heat removal (TSEC)", category: C.TRANSIENT, subcategory: "Loss of heat sink", states: ["POS-01", "POS-02", "POS-03"], method: "HBFT", trip: "High primary (pool) temperature / loss of intermediate flow", safety: ["Remove core heat"], barrier: BarrierImpactState.INTACT, screening: ScreeningStatus.RETAINED, importance: ImportanceLevel.HIGH, basis: "ANL-NSE-2 Sec. 5.2.5 (Table 5.10) quantifies loss of intermediate-sodium heat removal at 6.3E-1/yr from EBR-II plant history: inadvertent secondary-sodium dump, secondary-pump trip or controller error driving flow to zero, a secondary sodium leak, IHX degradation, or a primary-outlet pipe rupture. This is the primary loss-of-heat-sink (LOHS) initiator; the unprotected version (ULOHS) was screened unconditionally safe by EBR-II via the inlet-temperature coefficient. Found by the heat-balance fault tree on the intermediate loop." },
  { id: "IE-06", name: "Loss of steam-plant (balance-of-plant) heat removal (TBOP)", category: C.TRANSIENT, subcategory: "Loss of heat sink", states: ["POS-01", "POS-02", "POS-03"], method: "HBFT", trip: "High primary (pool) temperature / steam-plant trip", safety: ["Remove core heat"], barrier: BarrierImpactState.INTACT, screening: ScreeningStatus.RETAINED, importance: ImportanceLevel.MEDIUM, basis: "ANL-NSE-2 Sec. 5.2.5 (Table 5.10) gives loss of the ultimate steam/Rankine heat sink at 3.7E-1/yr: loss of condenser water or vacuum, loss of feedwater, steam-generator failure without sodium-water reaction, or turbine-generator trip. It is the second loss-of-heat-sink initiator and the largest single contributor to the non-anticipatory shutdown rate. Found by the heat-balance fault tree on the steam plant." },
  { id: "IE-07", name: "Control-rod-withdrawal slow reactivity insertion / transient overpower (RISA-B)", category: C.TRANSIENT, subcategory: "Reactivity insertion", states: ["POS-01", "POS-02", "POS-03"], method: "FMEA", trip: "High flux / high power / short period", safety: ["Control reactivity"], barrier: BarrierImpactState.INTACT, screening: ScreeningStatus.RETAINED, importance: ImportanceLevel.MEDIUM, basis: "ANL-NSE-2 Sec. 5.2.4 (Tables 5.3/5.10) treats slow positive reactivity insertion below ~0.65$ (RISA below 0.20$ at 3E-1/yr, RISB 0.20-0.65$ at 7.7E-3/yr), dominated by single- and multiple-control-rod insertion. This is the protected transient-overpower line and the precursor to the unprotected transient overpower (UTOP), bounded by the Doppler plus metallic-fuel axial-expansion feedbacks. Found by FMEA of the reactivity-control system." },
  { id: "IE-08", name: "Large multi-rod slow reactivity insertion (RISC-D)", category: C.TRANSIENT, subcategory: "Reactivity insertion", states: ["POS-01", "POS-02", "POS-03"], method: "FMEA", trip: "High flux / short period", safety: ["Control reactivity"], barrier: BarrierImpactState.INTACT, screening: ScreeningStatus.RETAINED, importance: ImportanceLevel.LOW, basis: "ANL-NSE-2 Sec. 5.2.4 (Table 5.10) treats the higher-worth slow reactivity insertions (RISC 0.65-1.10$ dominated by two-rod insertions, RISD above 1.10$ dominated by rod-bank insertions) as rare fault-tree events. They are the most limiting slow-TOP members and define the bounding reactivity challenge. Found by FMEA of the rod-control system." },
  { id: "IE-09", name: "Fast reactivity insertion from an experimental subassembly (RIFS)", category: C.TRANSIENT, subcategory: "Reactivity insertion", states: ["POS-01", "POS-02"], method: "PHA", trip: "High flux / short period", safety: ["Control reactivity"], barrier: BarrierImpactState.INTACT, screening: ScreeningStatus.RETAINED, importance: ImportanceLevel.LOW, basis: "ANL-NSE-2 Sec. 5.2.4 (Table 5.10) carries a fast sub-0.35$ reactivity insertion (RIFS) from gross material motion or internal failure inside an experimental subassembly at a screening value of 1E-3/yr, consistent with zero events in some 500 experimental subassemblies and controlled by experiment design and safety review. Surfaced by the process-hazard review of experiment reactivity." },
  { id: "IE-10", name: "Overcooling via a steam-side leak (OCSL)", category: C.TRANSIENT, subcategory: "Reactivity insertion", states: ["POS-01", "POS-02", "POS-03"], method: "HAZOP", trip: "High flux / low core-inlet temperature", safety: ["Control reactivity", "Remove core heat"], barrier: BarrierImpactState.INTACT, screening: ScreeningStatus.RETAINED, importance: ImportanceLevel.LOW, basis: "ANL-NSE-2 Sec. 5.2.6 (Table 5.10) quantifies overcooling via a major steam leak or stuck-open relief valves at 1E-1/yr (one event in the last 15 years). Overcooling of the secondary, then of the primary inlet through the IHX, inserts positive reactivity through the negative inlet-temperature coefficient. Found by HAZOP of the heat-transport line (deviation: more cooling)." },
  { id: "IE-11", name: "Overcooling via primary-pump run-up (OCPP)", category: C.TRANSIENT, subcategory: "Reactivity insertion", states: ["POS-01", "POS-02"], method: "HAZOP", trip: "High flux / low core-inlet temperature", safety: ["Control reactivity", "Remove core heat"], barrier: BarrierImpactState.INTACT, screening: ScreeningStatus.RETAINED, importance: ImportanceLevel.LOW, basis: "ANL-NSE-2 Sec. 5.2.6 (Table 5.10) quantifies overcooling from primary-pump flow run-up to maximum speed at 3E-1/yr (three events in the last 10 years), inserting positive reactivity through the reactivity-temperature feedback. Found by HAZOP of the primary-flow control line (deviation: more flow)." },
  { id: "IE-12", name: "Overcooling via secondary-pump run-up (OCSP)", category: C.TRANSIENT, subcategory: "Reactivity insertion", states: ["POS-01", "POS-02"], method: "HAZOP", trip: "High flux / low core-inlet temperature", safety: ["Control reactivity", "Remove core heat"], barrier: BarrierImpactState.INTACT, screening: ScreeningStatus.MERGED, importance: ImportanceLevel.LOW, basis: "ANL-NSE-2 Sec. 5.2.6 (Table 5.10) records overcooling from secondary (intermediate) pump run-up with zero observed events, a low screening value bounded by the same negative-feedback response as primary-pump run-up (IE-11). Merged into the pump-run-up overcooling event that already carries its impact." },
  { id: "IE-13", name: "Spurious reactor scram / general transient trip (SCRM)", category: C.TRANSIENT, subcategory: "Power-conversion transient", states: ["POS-01", "POS-02", "POS-03"], method: "GENLIST", trip: "Any reactor-protection trip signal (general trip)", safety: ["Control reactivity", "Remove core heat"], barrier: BarrierImpactState.INTACT, screening: ScreeningStatus.RETAINED, importance: ImportanceLevel.LOW, basis: "ANL-NSE-2 Sec. 5.2.11 (Tables 5.9/5.10) gives a spurious-scram rate of 7E-1/yr within a total scram-and-shutdown rate of 11.11/yr (of which about 7.5/yr are anticipatory). The non-anticipatory remainder is dominated by balance-of-plant faults, primary-pump faults, spurious scrams and electrical-supply faults. Seeded by the generic reactor-trip catch-all and confirmed by EBR-II operating data." },
  { id: "IE-14", name: "Rapid loss of primary sodium / loss of circulation (LCRA)", category: C.RCB_BREACH, subcategory: "Large primary sodium boundary breach", states: ["POS-01", "POS-02", "POS-03", "POS-04", "POS-05", "POS-06", "POS-07", "POS-08"], method: "MLD", trip: "Low primary sodium level / inter-vessel annulus leak detectors", safety: ["Maintain coolant inventory and the sodium boundary", "Remove core heat"], barrier: BarrierImpactState.BREACHED, screening: ScreeningStatus.RETAINED, importance: ImportanceLevel.HIGH, basis: "ANL-NSE-2 Sec. 5.2.8 (Table 5.10) treats rapid loss of primary sodium below the pump-inlet skirt as requiring simultaneous rupture of BOTH the primary vessel and the surrounding guard vessel (a full second primary boundary, not just a catch basin), giving a design-based frequency of order 1E-13/yr. The pool/double-vessel low-pressure design makes a true large primary loss-of-coolant effectively incredible; it is retained as the bounding boundary-breach member. Captured top-down by the master logic diagram coolant-inventory branch." },
  { id: "IE-15", name: "Delayed / slow primary sodium level drop (LCDL)", category: C.RCB_BREACH, subcategory: "Slow primary sodium leak", states: ["POS-01", "POS-02", "POS-03", "POS-04", "POS-05", "POS-06", "POS-07", "POS-08"], method: "HBFT", trip: "Low primary sodium level / inter-vessel annulus leak detectors and thermocouples", safety: ["Maintain coolant inventory and the sodium boundary", "Remove core heat"], barrier: BarrierImpactState.DEGRADED, screening: ScreeningStatus.RETAINED, importance: ImportanceLevel.MEDIUM, basis: "ANL-NSE-2 Sec. 5.2.9 (Table 5.10) sums the slow primary-sodium level-drop initiators (primary-vessel leak ~1E-8, biological-shield/tank breach ~5.2E-10, sodium purification/sampling-line leak ~4.4E-11, IHX-tube-plus-multiple-failure path ~1.2E-12) to a total of about 1.1E-8/yr, threatening the natural-circulation path if the level falls below the IHX inlet (~0.6 m). Sodium leak detectors and thermocouples in the inter-vessel annulus are credited. Found by the heat-balance fault tree on the inventory path." },
  { id: "IE-16", name: "Cover-gas boundary breach / cover-gas activity release", category: C.RCB_BREACH, subcategory: "Cover-gas boundary breach", states: ["POS-01", "POS-02", "POS-03", "POS-04", "POS-05", "POS-06", "POS-07", "POS-08", "POS-09"], method: "FMEA", trip: "Cover-gas area radiation / cover-gas pressure anomaly", safety: ["Maintain radionuclide barriers", "Maintain coolant inventory and the sodium boundary"], barrier: BarrierImpactState.BYPASSED, screening: ScreeningStatus.RETAINED, importance: ImportanceLevel.MEDIUM, basis: "The argon cover gas blanketing the primary sodium pool is a confinement barrier per the GIF SFR System Safety Assessment: it becomes radioactive (Ar-41 activation) and collects the noble fission gases Kr and Xe after a cladding breach. A breach or leak of the cover-gas boundary or its treatment line bypasses that barrier and releases the collected activity, a distinct release path from a sodium leak. Identified by FMEA of the cover-gas and gas-handling system." },
  { id: "IE-17", name: "Small steam-generator tube leak (slow water-into-sodium)", category: C.INTERFACING_SYSTEMS_RCB_BREACH, subcategory: "Steam-generator tube failure / sodium-water reaction", states: ["POS-01", "POS-02", "POS-03"], method: "OEREV", trip: "Cover-gas hydrogen monitor / secondary sodium pressure", safety: ["Maintain coolant inventory and the sodium boundary", "Remove core heat"], barrier: BarrierImpactState.BREACHED, screening: ScreeningStatus.MERGED, importance: ImportanceLevel.MEDIUM, basis: "GIF SFR System Safety Assessment Sec. 4.3.3 classifies steam-generator leaks as small (pin-hole, slow to detect and propagate), intermediate, and large. A small leak admits a low water/steam flow into the intermediate sodium, detected by cover-gas hydrogen monitoring. EBR-II's double-walled (duplex) tubes make this very low probability; it is bounded by and merged into the steam-generator tube rupture / sodium-water reaction event (IE-18) that carries the larger inventory of the same mechanism." },
  { id: "IE-18", name: "Steam-generator tube rupture / sodium-water reaction (SGTR)", category: C.INTERFACING_SYSTEMS_RCB_BREACH, subcategory: "Steam-generator tube failure / sodium-water reaction", states: ["POS-01", "POS-02", "POS-03"], method: "HBFT", trip: "Secondary sodium pressure spike / cover-gas hydrogen / rupture-disk actuation", safety: ["Maintain coolant inventory and the sodium boundary", "Remove core heat"], barrier: BarrierImpactState.BREACHED, screening: ScreeningStatus.RETAINED, importance: ImportanceLevel.HIGH, basis: "ANL-NSE-2 Sec. 5.2.7 (Table 5.10) gives steam-generator tube rupture leading toward sodium-water reaction a design-based screening frequency of 1E-4/yr (error factor 10) for EBR-II's conservative double-walled (duplex) tubes, which require breach of two welds, so no sodium-water reaction ever occurred in its history. The GIF SFR assessment (Sec. 4.3.3) describes the spike-shaped then quasi-steady pressure signature, hydrogen and corrosive-product generation, and the wastage propagation that can load the intermediate boundary and the IHX tubes (a containment-bypass concern). Operating precedent: Phenix and BN-600 sodium-water reaction events. Found by the heat-balance fault tree on the steam-generator boundary." },
  { id: "IE-19", name: "Intermediate heat exchanger (IHX) tube leak (primary-to-secondary sodium)", category: C.INTERFACING_SYSTEMS_RCB_BREACH, subcategory: "IHX tube failure / primary-to-secondary leak", states: ["POS-01", "POS-02", "POS-03", "POS-04"], method: "FMEA", trip: "Secondary sodium activity (Na-24) / IHX differential pressure", safety: ["Maintain coolant inventory and the sodium boundary", "Maintain radionuclide barriers"], barrier: BarrierImpactState.BREACHED, screening: ScreeningStatus.RETAINED, importance: ImportanceLevel.MEDIUM, basis: "The IHX transfers heat from radioactive primary sodium to non-radioactive secondary sodium, and its tubes are part of the primary boundary, so a tube leak is a primary-to-secondary leakage and containment-bypass concern (GIF SFR assessment; ANL-NSE-2 Sec. 5.2.9 lists the IHX-tube-plus-multiple-failure path among the slow primary-leak contributors). A leak carries Na-24 activity into the intermediate loop and, under a sodium-water-reaction overpressure, can be the path by which the pressure wave reaches the primary boundary. Identified by FMEA of the IHX." },
  { id: "IE-20", name: "Loss of constant power (LOCP, M-G clutch supply)", category: C.SPECIAL, subcategory: "Loss of electric power", states: ["POS-01", "POS-02", "POS-03", "POS-04"], method: "FMEA", trip: "Constant-power bus undervoltage / primary underflow", safety: ["Remove core heat", "Control reactivity"], barrier: BarrierImpactState.INTACT, screening: ScreeningStatus.RETAINED, importance: ImportanceLevel.MEDIUM, basis: "ANL-NSE-2 Sec. 5.2.3.2 (Table 5.10) quantifies loss of the constant-power electrical system supplying the M-G-set clutches at 1E-1/yr from EBR-II data and the constant-power-panel fault tree. Losing the clutch supply drops the coupling between the M-G sets and the primary pumps, a support-system route to loss of forced flow related to station-blackout-type sequences. Identified by FMEA of the constant-power distribution." },
  { id: "IE-21", name: "Loss of the NaK shutdown cooler (TSDC)", category: C.SPECIAL, subcategory: "Loss of dedicated decay-heat removal", states: ["POS-04", "POS-05", "POS-06", "POS-07", "POS-08"], method: "FMEA", trip: "Shutdown-cooler outlet temperature / NaK loop low flow", safety: ["Remove core heat"], barrier: BarrierImpactState.INTACT, screening: ScreeningStatus.RETAINED, importance: ImportanceLevel.MEDIUM, basis: "ANL-NSE-2 Sec. 5.2.10 (Table 5.10) gives break, leak or plugging of a NaK shutdown-cooler (decay-heat-removal) tube a fault-tree frequency of about 5.8E-3/yr, analogous to PFR air-dump-heat-exchanger failures and liquid-metal pipe-failure estimates. Loss of the dedicated passive NaK natural-circulation cooling path is most significant in the shutdown and refuelling states where it carries the load. Identified by FMEA of the shutdown-cooler system notebook." },
  { id: "IE-22", name: "Loss of shield cooling (TSHC)", category: C.SPECIAL, subcategory: "Loss of support cooling", states: ["POS-01", "POS-02", "POS-03", "POS-04", "POS-05", "POS-06", "POS-07", "POS-08"], method: "FMEA", trip: "Shield / thimble high temperature", safety: ["Remove core heat"], barrier: BarrierImpactState.INTACT, screening: ScreeningStatus.SCREENED_OUT, importance: ImportanceLevel.LOW, basis: "ANL-NSE-2 Sec. 5.2.10 (Table 5.10) records an extended loss of shield (thimble) cooling. The EBR-II PRA found that loss of support systems does not lead to the initiation of accident sequences with the single exception of loss of off-site power; the shield-cooling system removes about 150 kW and its loss yields a controlled shutdown with impaired but adequate decay-heat removal, not a plant-challenging initiator, so it is screened out under the support-system finding. Identified by FMEA of the shield-cooling system." },
  { id: "IE-23", name: "Loss of instrument air (TAIR)", category: C.SPECIAL, subcategory: "Loss of instrument air", states: ["POS-01", "POS-02", "POS-03", "POS-04", "POS-05", "POS-06", "POS-07", "POS-08"], method: "FMEA", trip: "Instrument-air header low pressure", safety: ["Remove core heat"], barrier: BarrierImpactState.INTACT, screening: ScreeningStatus.SCREENED_OUT, importance: ImportanceLevel.LOW, basis: "ANL-NSE-2 Sec. 5.2.10 (Table 5.10) records loss of the instrument-air support system at order 1.8E-1/yr from EBR-II data. Per the EBR-II PRA finding that support-system losses other than loss of off-site power do not initiate accident sequences, loss of instrument air drives air-operated valves to fail-safe and yields a controlled shutdown rather than a plant-challenging transient, so it is screened out. Identified by FMEA of the instrument-air system." },
  { id: "IE-24", name: "Local fault - metal driver-pin breach (MDLF)", category: C.SPECIAL, subcategory: "Local in-core fault", states: ["POS-01", "POS-02"], method: "FMEA", trip: "Cover-gas fission-gas monitor / fuel-element rupture detection", safety: ["Maintain radionuclide barriers"], barrier: BarrierImpactState.INTACT, screening: ScreeningStatus.RETAINED, importance: ImportanceLevel.LOW, basis: "ANL-NSE-2 Sec. 5.2.12 (Table 5.10) gives a slow local fault from a single metal driver-fuel-element (pin) breach a frequency of about 1.33E-1/yr (error factor 10), with the burnup limit set statistically for a 95% probability of fewer than one driver breach per roughly two-year core loading. The breach is detected by cover-gas fission-gas monitoring; it challenges the cladding barrier locally without a plant transient. Identified by FMEA of the driver-fuel performance." },
  { id: "IE-25", name: "Local fault - experimental-pin breach (MELF/OELF)", category: C.SPECIAL, subcategory: "Local in-core fault", states: ["POS-01", "POS-02"], method: "OEREV", trip: "Cover-gas fission-gas monitor / fuel-element rupture detection", safety: ["Maintain radionuclide barriers"], barrier: BarrierImpactState.INTACT, screening: ScreeningStatus.RETAINED, importance: ImportanceLevel.LOW, basis: "ANL-NSE-2 Sec. 5.2.12 (Table 5.10) gives a slow local fault from breach of a metal or oxide experimental fuel element about 4.5/yr each (error factor 3) from EBR-II operating data (roughly 90 metal-experiment breaches since about 1970, varying with the programmatic goals of the experimental reactor). These are routine, cover-gas-monitor-detected, benign breaches of an experiment pin; they dominate the local-fault frequency but not its consequence. Identified by the operating-experience review." },
  { id: "IE-26", name: "Local fault - partial subassembly flow blockage (SFPB)", category: C.SPECIAL, subcategory: "Local in-core fault", states: ["POS-01", "POS-02"], method: "FMEA", trip: "Subassembly-outlet temperature / cover-gas fission-gas monitor", safety: ["Remove core heat", "Maintain radionuclide barriers"], barrier: BarrierImpactState.INTACT, screening: ScreeningStatus.RETAINED, importance: ImportanceLevel.MEDIUM, basis: "ANL-NSE-2 Sec. 5.2.12 (Table 5.10) gives partial subassembly flow blockage (e.g. from an orificing error not caught by the argon flow test, which catches complete blockage) a frequency of about 1.4E-1/yr from three occasions in EBR-II history. Complete blockage (FLTA) is screened not credible at EBR-II given multiple coolant inlet ports per subassembly and flow testing. The partial-blockage member is the bounding local fault for consequence: the Fermi-1 1966 core melt was a flow blockage that partially melted two subassemblies. Identified by FMEA of the core thermal-hydraulics." },
  { id: "IE-27", name: "Long shutdown with secondary sodium drained (SHDL)", category: C.SPECIAL, subcategory: "Shutdown configuration", states: ["POS-06"], method: "OEREV", trip: "Pool temperature / shutdown-cooler status", safety: ["Remove core heat"], barrier: BarrierImpactState.INTACT, screening: ScreeningStatus.RETAINED, importance: ImportanceLevel.LOW, basis: "ANL-NSE-2 Sec. 5.2.11 (Tables 5.9/5.10) tracks the annual long shutdown with secondary sodium drained as a plant-state initiator at 1.0/yr (one long sodium-drained shutdown per year, each April), an impaired decay-heat-removal configuration in which the intermediate loop is unavailable and the NaK shutdown coolers and natural circulation carry the low decay-heat load. Captured by the operating-experience review of the EBR-II operating schedule." },
  { id: "IE-28", name: "Operator-induced reactivity insertion (erroneous control-rod withdrawal)", category: C.HUMAN_FAILURE, subcategory: "Operator-induced reactivity insertion", states: ["POS-01", "POS-02", "POS-03"], method: "MLD", trip: "High flux / high power / short period", safety: ["Control reactivity"], barrier: BarrierImpactState.INTACT, screening: ScreeningStatus.RETAINED, importance: ImportanceLevel.MEDIUM, basis: "ANL-NSE-2 Sec. 5.2.4 notes EBR-II actually experienced a single control-rod insertion from operator error, after which the control panel was modified. An operator erroneous withdrawal of an inserted rod or rod group is the human-failure counterpart of the RISA slow-insertion initiator, applicable when the core is critical or being made critical. Bounded by the Doppler and metallic-fuel expansion feedbacks plus scram. Surfaced top-down by the master logic diagram reactivity branch with explicit human-error treatment." },
  { id: "IE-29", name: "Operator subassembly loading / orificing error during refuelling (SFLE)", category: C.HUMAN_FAILURE, subcategory: "Operator refuelling error", states: ["POS-05"], method: "FMEA", trip: "Pre-startup flow test / reactivity-balance check", safety: ["Remove core heat", "Control reactivity"], barrier: BarrierImpactState.INTACT, screening: ScreeningStatus.RETAINED, importance: ImportanceLevel.LOW, basis: "ANL-NSE-2 Sec. 5.2.12 (Table 5.10) records a subassembly loading or orificing error during fuel handling at about 6E-2/yr (one detected loading error in 25 years of EBR-II operation, caught before operation). It is the credible refuelling-state human-failure initiator, applicable only during in-vessel fuel handling under sodium, and is detected by the argon flow test and reactivity-balance checks. Identified by FMEA of the fuel-handling line-up." },
  { id: "IE-30", name: "Operator inadvertent secondary-sodium dump / loss of intermediate heat removal", category: C.HUMAN_FAILURE, subcategory: "Operator-induced loss of heat sink", states: ["POS-01", "POS-02", "POS-03"], method: "HAZOP", trip: "High primary (pool) temperature / loss of intermediate flow", safety: ["Remove core heat"], barrier: BarrierImpactState.INTACT, screening: ScreeningStatus.RETAINED, importance: ImportanceLevel.MEDIUM, basis: "ANL-NSE-2 Sec. 5.2.5 lists an inadvertent secondary-sodium dump and a secondary-pump controller error among the contributors to loss of intermediate heat removal (TSEC). An operator commission error that dumps the secondary sodium or drives the secondary pump to zero during an evolution is the human-failure path into the loss-of-heat-sink state, distinct from the hardware-driven TSEC initiator. Bounded by the inlet-temperature coefficient and the passive pool heat sink. Surfaced by HAZOP of the secondary line-up (deviation: no intermediate flow)." },
  { id: "IE-31", name: "Operator-induced overcooling maneuver (erroneous pump run-up / steam-side)", category: C.HUMAN_FAILURE, subcategory: "Operator-induced overcooling", states: ["POS-01", "POS-02"], method: "HAZOP", trip: "High flux / low core-inlet temperature", safety: ["Control reactivity", "Remove core heat"], barrier: BarrierImpactState.INTACT, screening: ScreeningStatus.RETAINED, importance: ImportanceLevel.LOW, basis: "ANL-NSE-2 Sec. 5.2.6 carries overcooling transients (steam-side leak, primary- and secondary-pump run-up) as reactivity initiators. The human-failure subset is an erroneous primary-flow or secondary-side maneuver that overcools the core and inserts positive reactivity through the negative temperature coefficient, applicable only when the core is critical. Bounded by the negative feedback and the high-flux trip. Surfaced by HAZOP of the flow-control line-up (deviation: more flow / colder inlet)." },
  { id: "IE-32", name: "Internal sodium fire (spray or pool) affecting decay-heat-removal cabling", category: C.SPECIAL, subcategory: "Internal hazard - liquid-metal fire", states: ["POS-01", "POS-08"], method: "PHA", trip: "Fire and smoke detection / area high temperature", safety: ["Remove core heat", "Control reactivity"], barrier: BarrierImpactState.INTACT, screening: ScreeningStatus.RETAINED, importance: ImportanceLevel.MEDIUM, basis: "The dominant non-seismic internal hazard (HAZ-1): a secondary-sodium or NaK shutdown-cooler leak under the operating-floor deck plates burns through the CRDM, reactor-shutdown-system and primary-pump cabling in one fire zone, defeating forced flow, scram and a decay-heat-removal train together. Carried as the HZ-FIRE non-internal hazard group with fire detection and suppression credited downstream; the under-deck fire sequences drive the non-seismic external aggregate of about 3.6E-6/yr." },
  { id: "IE-33", name: "Seismic event (design-ground-motion exceedance)", category: C.SPECIAL, subcategory: "External hazard - seismic", states: ["POS-01"], method: "PHA", trip: "Seismic trip / loss of off-site power", safety: ["Control reactivity", "Remove core heat", "Maintain coolant inventory and the sodium boundary"], barrier: BarrierImpactState.INTACT, screening: ScreeningStatus.RETAINED, importance: ImportanceLevel.HIGH, basis: "The controlling external hazard (HAZ-8): vibratory ground motion at the site whose dominant fragility is the primary-tank and guard-vessel structure. Carried as the HZ-SEIS non-internal hazard group; the seismic contribution to fuel-damage frequency is 1.7E-5/yr (Roglans and Hill 1994), an order of magnitude above internal events, with the control-rod-drive system shown to retain high seismic capacity and passive natural circulation credited downstream." },
];

