    analysisMethods: ["NUREG-0612 / NUREG-0554 control-of-heavy-loads (single-failure-proof handling, load-path) analysis; RG 1.244", "OECD/NEA CNRA heavy-load-accident methodology and crane/rigging reliability analysis", "Fuel-handling criticality and count-rate-trip / interlock analysis (EBR-II unrestricted-fuel-handling interlock checks)", "Structural drop/impact analysis of the primary-tank cover, hangers and cover-gas boundary", "Human-reliability analysis (ASEP screening) for the fuel-handling loading plan and operator-termination actions"],
    screeningStatus: ScreeningStatus.SCREENED_OUT,
